<template>
  <div class="assistant-page">
    <header class="assistant-heading"><h1>{{ t('AI 助手','AI assistant') }}</h1></header>
    <div class="chat-layout">
      <section class="chat-main" :aria-label="t('AI 日程对话','AI chat')"><div class="messages" ref="messageArea" aria-live="polite">
        <div v-if="!messages.length" class="chat-welcome"><span>✦</span><h2>{{ t('安排你的日程','Plan your schedule') }}</h2><p>{{ t('上传课表，或输入想调整的安排。','Upload a timetable or describe a change.') }}</p></div>
        <article v-for="(m,index) in messages" :key="index" class="chat-message" :class="m.role"><span class="avatar"><template v-if="m.role==='user'">{{ t('你','You') }}</template><img v-else src="/brand.png" alt="Origin"/></span><div class="message-body"><p>{{ m.text }}</p><span v-if="m.fileName" class="attachment-tag">▧ {{ m.fileName }}</span><div v-if="m.actions?.length" class="plan-card"><header><strong>{{ t('待确认的日程变更','Review changes') }}</strong><span>{{ m.actions.length }} {{ t('项','changes') }}</span></header><div v-for="(a,n) in m.actions" :key="n" class="plan-item"><span class="action-type" :class="a.type">{{ {create:t('新增','Add'),update:t('修改','Edit'),delete:t('删除','Delete')}[a.type] }}</span><div><strong><i v-if="(a.schedule || a.original).color" class="schedule-color" :style="{backgroundColor:(a.schedule || a.original).color}" :title="(a.schedule || a.original).color"/>{{ (a.schedule || a.original).name }}</strong><p v-if="a.type==='update'" class="old-time">{{ t('原：','Before: ') }}{{ a.original.start_time }} → {{ a.original.end_time }}</p><p>{{ (a.schedule || a.original).start_time }} → {{ (a.schedule || a.original).end_time }}</p><p v-if="(a.schedule || a.original).location">{{ t('地点：','Location: ') }}{{ (a.schedule || a.original).location }}</p><p v-if="a.schedule?.note">{{ t('备注：','Notes: ') }}{{ a.schedule.note }}</p><p v-if="a.schedule?.reminder_time">{{ t('提醒：','Reminder: ') }}{{ a.schedule.reminder_time }}</p><p v-if="a.type==='update'">{{ t('状态：','Status: ') }}{{ a.schedule.is_completed ? t('已完成','Completed') : t('未完成','Incomplete') }} · {{ t('参与者：','People: ') }}{{ a.schedule.who.join('、') || t('无','None') }}</p><small v-if="a.state==='applied'">{{ t('已应用','Applied') }}</small></div></div><p class="plan-notice" v-if="m.notice">{{ m.notice }}</p><div v-if="m.state==='pending'" class="plan-actions"><button @click="apply(m)" :disabled="busy" class="confirm-plan">{{ t('确认应用','Apply') }} ({{ m.actions.length }})</button><button @click="m.state='discarded'" :disabled="busy">{{ t('放弃','Discard') }}</button></div><p v-else class="plan-state">{{ {applied:t('✓ 课表已更新','Schedule updated'),discarded:t('已放弃这次变更','Discarded'),error:t('应用已停止，请检查当前课表后重新生成','Stopped. Check your schedule before retrying.'),superseded:t('已被新的对话替代','Replaced by a newer plan')}[m.state] }}</p></div></div></article>
        <div v-if="busy" class="thinking" role="status">✦ {{ applying ? t('正在更新课表…','Updating…') : t('正在整理你的安排…','Thinking…') }}</div>
      </div>
      <div class="composer-area"><p v-if="storageError" class="chat-error">{{ t('设备存储空间不足，聊天记录暂时无法保存','Device storage is full. Chat could not be saved.') }}</p><div v-if="attachment" class="attached-file"><span>▧ {{ attachment.name }}</span><button @click="attachment=null" :disabled="busy" :aria-label="t('移除附件','Remove attachment')">×</button></div><p v-if="error" class="chat-error" role="alert">{{ error }}</p><form @submit.prevent="send" class="composer"><textarea v-model="draft" rows="2" maxlength="12000" :aria-label="t('发送给 AI 的内容','Message AI')" :placeholder="t('例如：明天下午有哪些课？','What classes do I have tomorrow afternoon?')" :disabled="busy" @keydown.ctrl.enter.prevent="send"/><div class="composer-bottom"><label class="upload-button" :class="{disabled:busy}">＋ {{ t('上传课表','Upload') }}<input type="file" accept="image/png,image/jpeg,image/webp,.txt,.csv,.json" @change="upload" :disabled="busy"/></label><span>Ctrl + Enter</span><button type="submit" :disabled="busy || (!draft.trim() && !attachment)">{{ t('发送','Send') }}</button></div></form><p class="send-notice">{{ t('对话、相关日程和附件将发送至','Chat, relevant schedules and attachments are sent to') }} {{ providerHost }}</p></div>
      </section></div>
  </div>
</template>
<script setup>
import { ref, computed, nextTick, onUnmounted } from 'vue'
import { t } from '../utils/i18n'
import { useChatHistory } from '../utils/chatHistory'
import { preferences, preferencesReady } from '../utils/preferences'
import { askAI } from '../utils/aiClient'
import { assertPlanFresh } from '../utils/aiPlan'
import { syncAlarms } from '../utils/scheduleAlarms'
import { syncWidget } from '../utils/scheduleWidget'
import request from '../utils/request'
const { draft, messages, busy, applying, storageError } = useChatHistory()
const attachment=ref(null),error=ref(''),messageArea=ref(null)
let disposed=false
onUnmounted(()=>{disposed=true})
nextTick(scrollBottom)
const providerHost=computed(()=>{try{return new URL(preferences.endpoint).host}catch{return '尚未配置的 AI 服务'}})
async function scrollBottom(){await nextTick();if(messageArea.value)messageArea.value.scrollTop=messageArea.value.scrollHeight}
async function loadSchedules(){const r=await request.get('/schedule');if(!r.data?.success)throw new Error(t('无法读取课表，请检查登录状态和网络','Unable to load schedules. Check your connection.'));return r.data.data||[]}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;error.value='';if(file.size>5*1024*1024){error.value=t('附件不能超过 5 MB','Attachments must be under 5 MB');return}try{if(['image/png','image/jpeg','image/webp'].includes(file.type)){const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});attachment.value={name:file.name,kind:'image',data}}else if(/\.(txt|csv|json)$/i.test(file.name)){const data=await file.text();if(data.length>50000)throw new Error(t('文本附件最多 50,000 字符，请按学期或月份拆分','Text attachments must be under 50,000 characters'));attachment.value={name:file.name,kind:'text',data}}else throw new Error(t('请选择 PNG、JPG、WEBP 或 TXT、CSV、JSON 文件','Choose PNG, JPG, WEBP, TXT, CSV or JSON'))}catch(e){error.value=e.message||t('文件读取失败','Unable to read file')}}
async function send(){
 if(busy.value||(!draft.value.trim()&&!attachment.value))return
 busy.value=true;error.value=''
 const text=draft.value.trim()||t('请帮我导入这份课表，缺失信息时先询问。','Import this schedule. Ask about missing details first.');const file=attachment.value
 let user
 try{
  await preferencesReady
  if(!preferences.apiKey)throw new Error(t('请先在设置中填写 API Key','Enter an API Key in Settings first'))
  const schedules=await loadSchedules()
  const previous=messages.value.at(-1)
  if(previous?.role==='user'&&previous.state==='failed'&&previous.text===text&&previous.fileName===file?.name){user=previous;user.state='sending'}
  else {user={role:'user',text,fileName:file?.name,file,state:'sending'};messages.value.push(user)}
  const history=messages.value.filter(m=>m!==user&&m.state!=='failed').map(m=>{
   let content=m.role==='assistant'?JSON.stringify({reply:m.text,actions:m.actions?.map(a=>({type:a.type,id:a.id,schedule:a.schedule})),state:m.state}):m.text
   if(m.file?.kind==='image')content=[{type:'text',text:m.text},{type:'image_url',image_url:{url:m.file.data}}]
   if(m.file?.kind==='text')content+=`\n${m.file.data}`
   return {role:m.role,content}
  })
  draft.value='';attachment.value=null;await scrollBottom()
  const plan=await askAI(text,file,schedules,history)
  user.state='sent'
  messages.value.forEach(m=>{if(m.state==='pending')m.state='superseded'})
  messages.value.push({role:'assistant',text:plan.reply,actions:plan.actions,state:'pending'})
 }catch(e){if(user)user.state='failed';error.value=e.message;draft.value=text;attachment.value=file}
 finally{busy.value=false;await scrollBottom()}
}
async function apply(m){if(busy.value||m.state!=='pending')return;busy.value=true;applying.value=true;error.value='';let sending=false;try{const current=await loadSchedules();assertPlanFresh(m.actions,current);for(const a of m.actions){if(disposed)throw new Error(t('页面已切换，已停止继续应用','Stopped because the page changed'));sending=true;let r;if(a.type==='delete')r=await request.delete(`/schedule/${a.id}`);else if(a.type==='update')r=await request.put(`/schedule/${a.id}`,{...a.schedule,id:a.original.id});else r=await request.post('/schedule',a.schedule);if(!r.data?.success)throw new Error(t('服务器未确认这项变更','The server did not confirm this change'));a.state='applied';sending=false;}m.state='applied';m.notice='';if(disposed)return;const updated=await loadSchedules();if(disposed)return;await syncWidget(updated.map(s=>({title:s.name,date:s.start_time.slice(0,10),start:s.start_time.slice(11,16),end:s.end_time.slice(11,16),location:s.location})));try{await syncAlarms(updated)}catch{m.notice=t('课表已更新，但闹钟同步失败，请到 Settings 重新保存设置','Schedule updated. Open Settings to retry alarm sync.')}}catch(e){if(m.state==='applied')m.notice='变更已保存，但刷新失败，请返回课表检查并同步闹钟';else{m.state='error';m.notice=`${e.message}。已确认 ${m.actions.filter(a=>a.state==='applied').length} 项。${sending?'最后一次请求可能已保存，请先检查课表，避免重复添加。':''}`}}finally{busy.value=false;applying.value=false;await scrollBottom()}}
</script>
<style scoped>
.assistant-page{max-width:1180px;margin:auto;padding:30px 28px;color:#20344a}.assistant-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:25px}.eyebrow{font-size:9px;color:#409eff;letter-spacing:2px;font-weight:700}h1{font-size:32px;letter-spacing:-1px;margin:10px 0}h1 span{font-size:22px;color:#409eff;margin-left:13px}.assistant-heading p{color:#8a96a4;font-size:13px;margin:0}.settings-link{font-size:12px;text-decoration:none;color:#66829d;background:#fff;border:1px solid #e3eaf3;border-radius:10px;padding:12px;white-space:nowrap}.chat-layout{display:grid;grid-template-columns:minmax(0,1fr);border:1px solid #e4ebf3;border-radius:22px;overflow:hidden;background:white;height:calc(100dvh - 235px);min-height:520px;max-height:900px;box-shadow:0 10px 40px #2b5b8f0a}.assistant-sidebar{padding:28px 22px;background:#f0f7ff;min-width:0}.assistant-mark{display:grid;place-items:center;width:44px;height:44px;background:#409eff;color:white;border-radius:14px;font-size:26px}.assistant-sidebar h2{font-size:18px;margin:20px 0 10px}.assistant-sidebar>p{font-size:12px;line-height:1.9;color:#7e93a9}.provider-status{font-size:11px;color:#7792ab;display:flex;align-items:center;gap:7px;margin-top:20px;overflow-wrap:anywhere}.provider-status i{width:6px;height:6px;background:#c9d4df;border-radius:50%;flex-shrink:0}.provider-status i.ready{background:#54b797}.sidebar-rule{height:1px;background:#dce8f4;margin:25px 0}.assistant-sidebar>strong{font-size:11px;color:#6f879e}.assistant-sidebar>button{display:flex;gap:9px;align-items:center;justify-content:space-between;text-align:left;width:100%;background:white;border:1px solid #e3edf7;border-radius:10px;padding:13px;margin-top:11px;color:#5e7b98;font-size:11px;line-height:1.7;cursor:pointer}.assistant-sidebar>button span{color:#409eff}.sidebar-note{font-size:10px;color:#92a5b8;line-height:2;margin-top:26px}.chat-main{display:flex;flex-direction:column;min-height:0;min-width:0}.messages{flex:1;min-height:0;overflow-y:auto;padding:28px;scroll-behavior:smooth}.chat-welcome{min-height:230px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center}.chat-welcome>span{color:#409eff;font-size:32px;background:#f0f7ff;padding:10px 18px;border-radius:20px}.chat-welcome h2{font-size:20px;margin-top:22px}.chat-welcome p{font-size:12px;color:#8a96a4;line-height:2}.chat-message{display:flex;align-items:flex-start;gap:10px;margin-bottom:23px}.avatar{font-size:12px;width:28px;height:28px;background:#eaf4ff;color:#409eff;border-radius:9px;display:grid;place-items:center;flex-shrink:0}.message-body{min-width:0;max-width:100%;flex:1}.message-body>p{margin:0;background:#f5f8fc;padding:13px 16px;border-radius:0 13px 13px;font-size:13px;white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere}.user .message-body>p{background:#eaf4ff}.attachment-tag{display:inline-block;font-size:11px;color:#7792ab;margin:9px 0;overflow-wrap:anywhere}.plan-card{border:1px solid #dfebf8;border-radius:13px;margin-top:14px;overflow:hidden}.plan-card>header{display:flex;justify-content:space-between;background:#f1f7ff;padding:13px;font-size:12px}.plan-card>header span{color:#7792ab}.plan-item{display:flex;gap:9px;padding:13px;border-bottom:1px solid #eef2f7}.action-type{font-size:10px;color:#409eff;background:#eaf4ff;padding:4px 6px;border-radius:5px;height:fit-content;white-space:nowrap}.action-type.delete{background:#fff0ef;color:#dc6860}.action-type.update{background:#fff5e6;color:#ba8d48}.plan-item>div{min-width:0;overflow-wrap:anywhere}.plan-item strong{font-size:12px}.plan-item p{font-size:11px;color:#7f93a7;margin:6px 0;line-height:1.6}.plan-item .old-time{text-decoration:line-through;color:#a7b3bf}.plan-item small{color:#54aa8a}.plan-actions{display:flex;gap:10px;padding:13px;flex-wrap:wrap}.plan-actions button{background:#f1f5fa;border:0;border-radius:7px;padding:10px 13px;color:#6f859a;font-size:11px;cursor:pointer}.plan-actions .confirm-plan{background:#409eff;color:white}.plan-notice,.plan-state{font-size:11px;padding:0 13px;line-height:1.8;color:#8a96a4}.thinking{font-size:12px;color:#409eff;padding:12px}.composer-area{padding:0 22px 14px}.composer{border:1px solid #dce7f3;border-radius:14px;padding:12px;background:#fbfdff}.composer:focus-within{border-color:#409eff}.composer textarea{box-sizing:border-box;width:100%;resize:vertical;max-height:160px;min-height:48px;background:none;border:0;outline:none;font-family:inherit;font-size:13px;color:#20344a;line-height:1.8}.composer-bottom{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:8px}.upload-button{font-size:11px;color:#7190af;cursor:pointer}.upload-button input{display:none}.composer-bottom>span{font-size:9px;color:#afbbc7}.composer-bottom button{border:0;background:#409eff;color:white;padding:10px 15px;border-radius:8px;cursor:pointer;font-size:12px}.send-notice{font-size:9px;color:#9aabba;text-align:center;line-height:1.8;overflow-wrap:anywhere;margin-bottom:0}.send-notice strong{font-weight:400}.attached-file{display:flex;justify-content:space-between;gap:10px;font-size:11px;background:#f1f7ff;padding:9px;border-radius:8px;margin-bottom:9px;overflow-wrap:anywhere}.attached-file button{background:none;border:0;color:#7e93a9}.chat-error{font-size:12px;color:#cb615a;line-height:1.7;margin:10px 0}button:disabled{opacity:.5;cursor:default}.disabled{opacity:.5}@media(max-width:760px){.assistant-page{padding:22px 12px 15px}.assistant-heading{margin-bottom:18px;padding:0 6px}.assistant-heading h1{font-size:27px}.assistant-heading p{font-size:11px}.eyebrow{font-size:7px;letter-spacing:1px}.settings-link{padding:10px;font-size:11px}.assistant-sidebar{display:none}.chat-layout{grid-template-columns:1fr;height:calc(100dvh - 210px);min-height:460px;border-radius:17px}.messages{padding:20px 13px}.composer-area{padding:0 12px 12px}.chat-welcome h2{font-size:18px}.chat-welcome p{font-size:11px}.composer-bottom>span{display:none}.message-body>p{font-size:12px}.plan-item{padding:10px}.plan-item p{font-size:10px}}
</style>

<style scoped>.assistant-heading h1{margin:0}.chat-layout{height:calc(100dvh - 155px);min-height:380px}@media(max-width:760px){.chat-layout{height:calc(100dvh - 145px);min-height:340px}}</style>

<style scoped>.avatar img{width:100%;height:100%;object-fit:cover;border-radius:9px}</style>

<style scoped>.schedule-color{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:7px;vertical-align:middle}</style>
